insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('rag-fundamentals','rag-fundamentals','RAG — יסודות וארכיטקטורה','concept','RAG מחבר שליפת מידע ממקורות חיצוניים ליצירת תשובה על ידי מודל. הפרק מפריד בין הכנת המידע, אחזור ההקשר ובניית תשובה עם ראיות, ומסביר מדוע שליפה טובה אינה מבטיחה תשובה נכונה.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02. דוגמאות ותרגילים פדגוגיים מוצעים ולא הורצו; תאריכי השקה שלא אומתו נשארו חסרים.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approval 2026-11-02: expand RAG category to eight entries; docs/DECISIONS.md D-030');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('haystack','haystack','Haystack','framework','מסגרת קוד פתוח של deepset לבניית Pipelines של חיפוש, RAG ויישומי מודלים. מאפשרת לחבר רכיבי הכנת מסמכים, שליפה ויצירה ולבחון את גבולות האחריות של כל שלב.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02. דוגמאות ותרגילים פדגוגיים מוצעים ולא הורצו; תאריכי השקה שלא אומתו נשארו חסרים.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approval 2026-11-02: expand RAG category to eight entries; docs/DECISIONS.md D-030');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('ragflow','ragflow','RAGFlow','platform','מערכת קוד פתוח שמחברת עיבוד מסמכים, ניהול ידע ויכולות RAG. היא נקודת השוואה למי שרוצה לבחון מערכת משולבת סביב ידע ושליפה, במקום להרכיב כל שלב מספריות נפרדות.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02. דוגמאות ותרגילים פדגוגיים מוצעים ולא הורצו; תאריכי השקה שלא אומתו נשארו חסרים.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approval 2026-11-02: expand RAG category to eight entries; docs/DECISIONS.md D-030');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('docling','docling','Docling','sdk','כלי לעיבוד מסמכים ולהמרתם לייצוג מובנה, כולל התייחסות למבנה עמוד, טבלאות ו־OCR לפי תצורה. ממוקם לפני האינדוקס והשליפה; אינו מסגרת RAG שלמה או מסד וקטורי.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02. דוגמאות ותרגילים פדגוגיים מוצעים ולא הורצו; תאריכי השקה שלא אומתו נשארו חסרים.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approval 2026-11-02: expand RAG category to eight entries; docs/DECISIONS.md D-030');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('unstructured','unstructured','Unstructured','sdk','ספרייה ומערך שירותים להכנת מסמכים: חלוקה לרכיבי תוכן, חילוץ metadata וחלוקה למקטעים. הפרק מבדיל בין ספריית הקוד הפתוח לבין API ושירותים מסחריים, ואינו מציג אותם כבעלי יכולות זהות.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02. דוגמאות ותרגילים פדגוגיים מוצעים ולא הורצו; תאריכי השקה שלא אומתו נשארו חסרים.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approval 2026-11-02: expand RAG category to eight entries; docs/DECISIONS.md D-030');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('microsoft-graphrag','microsoft-graphrag','Microsoft GraphRAG','framework','מערכת RAG מודולרית של Microsoft שמשלבת ייצוג גרפי ותהליכי אינדוקס ושליפה. מיועדת ללימוד מתקדם של שאלות וקשרים על אוספי מידע; המותג Microsoft אינו מעיד על SDK מקומי ב־C#.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02. דוגמאות ותרגילים פדגוגיים מוצעים ולא הורצו; תאריכי השקה שלא אומתו נשארו חסרים.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approval 2026-11-02: expand RAG category to eight entries; docs/DECISIONS.md D-030');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('lightrag','lightrag','LightRAG','framework','פרויקט RAG של HKUDS שמשלב ידע גרפי עם שליפה, ומציע גם כלי שירות וממשק לעבודה עם אוספי מידע. זהו כלי מתקדם להשוואת גישות, לא הוכחה לכך שכל RAG זקוקה לגרף.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02. דוגמאות ותרגילים פדגוגיים מוצעים ולא הורצו; תאריכי השקה שלא אומתו נשארו חסרים.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approval 2026-11-02: expand RAG category to eight entries; docs/DECISIONS.md D-030');
