insert into academy.entry_categories (entry_id,category_id,position) values ('rag-fundamentals','04',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('rag-fundamentals','היכרות עם REST/JSON, SQL, הרשאות ומודל שפה.','תרחיש לימודי מוצע, שלא הורץ כאן: משתמש שואל על מדיניות רכש. שרת ASP.NET Core מאמת הרשאות, שולף רק נהלים שהמשתמש רשאי לקרוא, ומבקש מהמודל תשובה עם מזהי סעיפים. כשאין סעיף מתאים הוא מחזיר חוסר מידע במקום להמציא אישור רכש.','תכננו עשר שאלות, כולל שאלה שאין עליה תשובה ומסמך שהמשתמש אינו מורשה לראות. הגדירו כיצד בודקים שליפה, ציטוטים ומחיקת מקור; השוו חיפוש מילולי לבסיס היברידי.','RAG היא ארכיטקטורה שאינה תלויה בשפה או בספק. אפשר לממש אותה ב־C#/.NET, Python או TypeScript. השפה של ספרייה מסוימת היא שאלה נפרדת; קריאה ב־REST לשירות Python אינה SDK מקומי ל־.NET.','RAG אינה חלופה ישירה ל־fine-tuning: שליפה מספקת הקשר ממקורות, ואימון משנה התנהגות או ידע במשקלי המודל. לפעמים SQL או חיפוש רגיל מספיקים בלי יצירת תשובה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('rag-fundamentals',0,'איזו בעיה RAG פותרת?','מודל לבדו אינו מאגר המסמכים הארגוני. RAG מוסיפה מידע שנשלף בזמן השאלה כדי לבסס תשובה על מקורות נבחרים; זו אינה הבטחה לאמת או תחליף להרשאות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('rag-fundamentals',1,'הכנת מידע ואינדוקס','מחלצים תוכן ומבנה, מחלקים למקטעים ושומרים מזהה מסמך, גרסה ו־metadata. אפשר לחשב embeddings לצורך חיפוש סמנטי. OCR או חילוץ טבלאות לקוי פוגעים בתשובה עוד לפני קריאת המודל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('rag-fundamentals',2,'שליפה ובניית תשובה','אפשר לשלב התאמה מילולית וסמנטית בחיפוש היברידי, ולסדר מועמדים מחדש ב־reranking. רק הקשר מתאים עובר למודל, עם הנחיה לצטט מקורות ולציין כשאין מספיק ראיות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('rag-fundamentals',3,'איך משווים פתרונות?','בדיקה פדגוגית: הפרידו בין כיסוי שליפה, נאמנות התשובה למקור, נכונות ההפניות, זמן ועלות. השוו baseline פשוט לשינוי אחד בכל פעם; יותר מקטעים או גרף ידע אינם שיפור מובטח.');
insert into academy.entry_sections (entry_id,position,title,body) values ('rag-fundamentals',4,'הרשאות, עדכניות ובטיחות','סננו מידע לפי משתמש וארגון לפני העברתו למודל. מסמך הוא קלט לא מהימן, לא הוראת מערכת. יש לטפל במחיקה ובעדכון אינדקס ולהימנע מחשיפת תוכן סודי גם כשנוסח השאלה תמים.');
insert into academy.entry_sources (entry_id,position,source_url,title,checked_at,supports) values ('rag-fundamentals',0,'https://developers.llamaindex.ai/python/framework/understanding/rag/','RAG — יסודות וארכיטקטורה — מקור רשמי','2026-11-02','תפקיד, תהליך ושפות; הדוגמאות וההשוואות הן תכנון פדגוגי של האקדמיה.');
