insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('rag-fundamentals','יסודות שילוב שליפת מידע ויצירת תשובה, מהכנת מסמכים ועד הקשר, מקורות והערכת איכות.','RAG היא ארכיטקטורה שאינה תלויה בשפה או בספק. אפשר לממש אותה ב־C#/.NET, Python או TypeScript. השפה של ספרייה מסוימת היא שאלה נפרדת; קריאה ב־REST לשירות Python אינה SDK מקומי ל־.NET.','not_applicable','פרק מושגים, ללא מאגר מייצג או שנת השקה של מוצר.','2026-11-02');
