insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('haystack','היכרות עם REST/JSON, SQL, הרשאות ומודל שפה. מומלץ להתחיל בפרק RAG — יסודות וארכיטקטורה.','דוגמה לימודית מוצעת: שירות Python מאחזר נהלי תמיכה ומחזיר תשובה עם מזהי מסמכים ל־API של .NET. ה־API בודק הרשאות ומחזיר ל־React את התשובה והמקורות; המודל אינו מקבל גישה חופשית למסד.','תכננו Pipeline עם שליפה ויצירה, ואז החליפו רק את רכיב השליפה. הגדירו בדיקות למקורות חסרים, מסמך לא מורשה ושאלה ללא תשובה.','מסגרת Haystack שנבדקה מיועדת ל־Python. לא אומת SDK מקומי של המסגרת ב־C#/.NET או TypeScript. אפשר לתכנן שירות Python עם חוזה HTTP ולצרוך אותו מ־ASP.NET Core; זו הפרדת שירותים, לא שוויון SDKs.','LlamaIndex היא חלופה קיימת לבניית RAG בקוד; RAGFlow היא מערכת משולבת יותר. מסד וקטורי הוא רכיב אחסון ושליפה, לא חלופה מלאה למסגרת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('haystack',0,'איזו בעיה היא פותרת?','Haystack מספקת מסגרת לחיבור רכיבי חיפוש, שליפה ויישומי מודלים. שימושים מרכזיים כוללים שאלות על מסמכים ותהליכי עיבוד מידע שבהם רוצים להפריד רכיבים במקום לכתוב שרשרת קריאות בלתי מפורשת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('haystack',1,'איך בנוי התהליך?','Pipeline מחבר רכיבים עם קלט ופלט מוגדרים. הכנת האינדקס והרצת שאילתה הן תהליכים נפרדים. בדומה לשירותי .NET, כדאי לבדוק רכיב שליפה בנפרד מרכיב יצירת התשובה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('haystack',2,'שימושים מרכזיים','עוזר נהלים, חיפוש מסמכים ובניית תשובה המבוססת על מסמכים שנשלפו. חיבורים למודלים ולמאגרי מסמכים תלויים בגרסה ובאינטגרציה שנבחרה; אין להניח שכל חיבור זהה בהתנהגותו.');
insert into academy.entry_sections (entry_id,position,title,body) values ('haystack',3,'השוואה ובחירה','השוואה פדגוגית: מול LlamaIndex בחנו API לשליפה, חיבור למקורות, בדיקות ושמירת metadata. מול RAGFlow השוו שליטה בקוד להקמת מערכת משולבת. Docling ו־Unstructured מכינות מסמכים ועשויות להשתלב, ולא להחליף את התזמור.');
insert into academy.entry_sections (entry_id,position,title,body) values ('haystack',4,'תפעול ובטיחות','יש לנהל הרשאות למקורות, גרסאות אינדקס ושמירת סודות. חיבור למודל חיצוני מחייב לדעת איזה תוכן נשלח אליו. הצלחת Pipeline טכנית אינה הוכחה שהתשובה נכונה או שהמקור מורשה.');
insert into academy.entry_sources (entry_id,position,source_url,title,checked_at,supports) values ('haystack',0,'https://haystack.deepset.ai/overview/intro','Haystack — מקור רשמי','2026-11-02','תפקיד, תהליך ושפות; הדוגמאות וההשוואות הן תכנון פדגוגי של האקדמיה.');
