insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('haystack','מסגרת Python להרכבת תהליכי חיפוש ושליפה, עיבוד מידע ויצירת תשובות מבוססות הקשר.','מסגרת Haystack שנבדקה מיועדת ל־Python. לא אומת SDK מקומי של המסגרת ב־C#/.NET או TypeScript. אפשר לתכנן שירות Python עם חוזה HTTP ולצרוך אותו מ־ASP.NET Core; זו הפרדת שירותים, לא שוויון SDKs.','verified','המאגר הרשמי של הפרויקט. Stars הם צילום מצב, ופעילות היא תאריך Commit בראש ברירת המחדל לפי UTC; אין ציון איכות או תפוצה.','2026-11-02T19:41:23.349Z');
