insert into academy.entry_categories (entry_id,category_id,position) values ('ragflow','04',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('ragflow','היכרות עם REST/JSON, SQL, הרשאות ומודל שפה. מומלץ להתחיל בפרק RAG — יסודות וארכיטקטורה.','תרחיש לימודי מוצע: צוות מעלה נהלים סינתטיים לסביבת ניסוי מבודדת ובוחן שאלות עם הפניות למקור. יישום .NET משמש שער הרשאות לצריכת API ומציג תוצאות ב־React, ללא העברת הרשאות מנהל לדפדפן.','הכינו טבלת קריטריונים להערכת RAGFlow מול LlamaIndex: חילוץ, הרשאות, עדכון, מקור ועלות תפעול. הגדירו בדיקה שנכשלת אם מסמך שנמחק ממשיך להופיע.','המערכת כוללת backend באקוסיסטם Python וממשק/API. אין להציג רכיבי ממשק כ־SDK סוכנים. שילוב C#/.NET יכול להיעשות כצרכן HTTP של שירות RAGFlow עם אימות; לא אומתה כאן ספריית ליבה מקומית ל־.NET.','Haystack ו־LlamaIndex הן חלופות להרכבת התהליך בקוד. Docling ו־Unstructured מטפלות בהכנת מסמכים; הן אינן מערכת RAG שלמה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ragflow',0,'איזו בעיה היא פותרת?','RAGFlow מאגדת יכולות סביב הכנת מסמכים, ידע ושליפה עבור יישומי מודלים. שימושים מרכזיים הם בסיסי ידע ועוזרי מסמכים; יש לבדוק את היכולות הנדרשות בגרסה הנבחרת ולא להסתפק בשם המוצר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ragflow',1,'איך בנויה המערכת?','הכנת המסמכים בונה ייצוג לחיפוש, ושאלות משתמש מפעילות שליפה ויצירת תשובה. ממשק ניהול ו־API מוסיפים שכבת מערכת סביב השלבים; נדרשת אחריות על פריסה, משאבים ואבטחה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ragflow',2,'שימושים מרכזיים','הערכת מערכת ידע ארגונית על אוסף מסמכים ובניית חוויית שאלות ותשובות. בחנו איכות חילוץ, יכולת עדכון מקורות ושיוך הפניות, לפני הרחבת האוסף או הוספת יכולות סוכן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ragflow',3,'השוואה ובחירה','השוואה פדגוגית: מול Haystack ו־LlamaIndex בדקו האם מערכת משולבת חוסכת עבודת מוצר, ומה המחיר בגמישות ובתפעול. מול Docling ההבדל הוא בין מערכת ידע לבין רכיב עיבוד מסמכים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ragflow',4,'תפעול ובטיחות','בדקו הרשאות, מחיקת מסמכים, הגבלת גישה ל־API וגיבויים. חשיפת ממשק ניהול אינה דרך לשתף סודות. אין צורך להתקין את המערכת כדי ללמוד את תפקידה, ולא הורצה כאן סביבת RAGFlow.');
insert into academy.entry_sources (entry_id,position,source_url,title,checked_at,supports) values ('ragflow',0,'https://github.com/infiniflow/ragflow','RAGFlow — מקור רשמי','2026-11-02','תפקיד, תהליך ושפות; הדוגמאות וההשוואות הן תכנון פדגוגי של האקדמיה.');
