insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('ragflow','should_know','כדאי להכיר להשוואה בין מערכת RAG משולבת לבין תהליך שמרכיבים בעצמנו בקוד, כולל עלות תפעול ומידת השליטה.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('ragflow','מערכת משולבת להכנת מסמכים, ניהול ידע ושליפה, בדרך לתשובות המבוססות על מקורות.','המערכת כוללת backend באקוסיסטם Python וממשק/API. אין להציג רכיבי ממשק כ־SDK סוכנים. שילוב C#/.NET יכול להיעשות כצרכן HTTP של שירות RAGFlow עם אימות; לא אומתה כאן ספריית ליבה מקומית ל־.NET.','verified','המאגר הרשמי של הפרויקט. Stars הם צילום מצב, ופעילות היא תאריך Commit בראש ברירת המחדל לפי UTC; אין ציון איכות או תפוצה.','2026-11-02T19:41:23.896Z');
