insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('docling','היכרות עם REST/JSON, SQL, הרשאות ומודל שפה. מומלץ להתחיל בפרק RAG — יסודות וארכיטקטורה.','תרחיש לימודי מוצע: המרת PDF סינתטי עם טבלת מלאי לייצוג מובנה, בדיקת התוצאה ושמירת metadata. לאחר מכן LlamaIndex מאנדקסת את התוכן, ו־ASP.NET Core מגיש שאלות מורשות עם מקור.','בחרו מסמך עברי עם שתי עמודות וטבלה. הגדירו בדיקה ידנית של סדר קריאה, ערכים וטבלאות והשוו לפלט Unstructured לפני יצירת embeddings.','הספרייה המרכזית שנבדקה היא Python. שילוב C#/.NET יכול להיעשות דרך שירות המרה נפרד ו־HTTP או דרך תוצרי קבצים; אין בכך SDK מקומי מאומת ל־.NET. יש לבדוק תלות במודלי OCR ובמשאבי העיבוד הנבחרים.','Unstructured היא כלי השוואה להכנת מסמכים. LlamaIndex ו־Haystack מטפלות בחלקים אחרים של התהליך; לא מדרגים אותן כתחליפים זהים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('docling',0,'איזו בעיה הוא פותר?','מסמך PDF אינו בהכרח רצף טקסט קריא. Docling מטפלת בהמרת תוכן ומבנה לייצוג שניתן לעבד; זהו שלב הכנת ידע לפני בחירת מודל או חיפוש.');
insert into academy.entry_sections (entry_id,position,title,body) values ('docling',1,'איך בנוי התהליך?','קלט מסמך עובר ניתוח והמרה לפי סוג ותצורה. התוצר יכול לשמור רכיבי מבנה, ולא רק טקסט גולמי. אחריו בוחרים כיצד לחלק למקטעים ולשמר קשר למקור.');
insert into academy.entry_sections (entry_id,position,title,body) values ('docling',2,'שימושים מרכזיים','הכנת נהלים, דוחות וטבלאות לאינדוקס ולניתוח. OCR וחילוץ דורשים בדיקה על המסמכים והשפות שלכם; תמיכה בפורמט אינה מבטיחה דיוק בכל סריקה בעברית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('docling',3,'השוואה ובחירה','השוואה פדגוגית: מול Unstructured השוו מבנה, טבלאות, שגיאות וצריכת משאבים על אותו אוסף. LlamaIndex ו־Haystack יכולות לשמש שכבת התזמור בהמשך. Docling אינה מחזירה לבדה מערכת שאלות ותשובות מלאה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('docling',4,'איכות ובטיחות','שמרו מזהה מסמך וגרסה, ובדקו שלא התהפך סדר עמודות או אבד קשר בין כותרת לתוכן. בידקו מידע אישי, תלות במודלים חיצוניים והגבלות משאבים לפני הכנסה ל־Pipeline ארגוני.');
insert into academy.entry_sources (entry_id,position,source_url,title,checked_at,supports) values ('docling',0,'https://docling-project.github.io/docling/','Docling — מקור רשמי','2026-11-02','תפקיד, תהליך ושפות; הדוגמאות וההשוואות הן תכנון פדגוגי של האקדמיה.');
