insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('docling','כלי Python לחילוץ מבנה ותוכן ממסמכים ולהכנתם לחלוקה למקטעים ולאינדוקס ידע.','הספרייה המרכזית שנבדקה היא Python. שילוב C#/.NET יכול להיעשות דרך שירות המרה נפרד ו־HTTP או דרך תוצרי קבצים; אין בכך SDK מקומי מאומת ל־.NET. יש לבדוק תלות במודלי OCR ובמשאבי העיבוד הנבחרים.','verified','המאגר הרשמי של הפרויקט. Stars הם צילום מצב, ופעילות היא תאריך Commit בראש ברירת המחדל לפי UTC; אין ציון איכות או תפוצה.','2026-11-02T19:41:24.431Z');
