insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('unstructured','היכרות עם REST/JSON, SQL, הרשאות ומודל שפה. מומלץ להתחיל בפרק RAG — יסודות וארכיטקטורה.','דוגמה לימודית מוצעת: עיבוד קובצי Word ו־PDF סינתטיים לרכיבי תוכן, שמירת מזהה מקור והזנת Pipeline של Haystack. .NET מנהל הרשאות ומעקב גרסאות ואינו שולח מסמכים אמיתיים לשירות חיצוני בתרגיל.','השוו את מספר המקטעים ואת הקשר למקור לפני ואחרי chunking. הסבירו מה משתנה תפעולית כשעוברים מספרייה מקומית ל־API מנוהל.','הפרק ומדידת GitHub מתייחסים לספריית Python בקוד פתוח. C#/.NET יכול לצרוך שירות עיבוד דרך HTTP לפי API שנבחר; זו אינה תמיכת .NET מקורית בספרייה. SDKs ויכולות של שירות מסחרי צריכים להיבדק בנפרד.','Docling מספקת גישת הכנת מסמכים להשוואה. Haystack ו־LlamaIndex מרכיבות את תהליך ה־RAG בהמשך; אין לבלבל בין שכבת הכנה לשכבת יצירת תשובות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('unstructured',0,'איזו בעיה היא פותרת?','Unstructured מכינה מסמכים לעיבוד על ידי חילוץ רכיבים כגון טקסט, כותרות ו־metadata. התוצרים יכולים להזין אינדקס RAG; הספרייה עצמה אינה מודל שפה או מסד וקטורי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('unstructured',1,'איך בנוי התהליך?','Partitioning מחלקת מסמך לרכיבי תוכן, ו־chunking מארגנת אותם למקטעים להמשך עיבוד. חשוב לשמר מקור וגרסה ולבחון כיצד טבלאות ורכיבים מורכבים עוברים בין השלבים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('unstructured',2,'ספרייה לעומת שירות','התיעוד מבדיל בין ספריית הקוד הפתוח לבין API ו־Pipelines מנוהלים, ומציין מגבלות לספרייה. אין להסיק שמחיר, ביצועים, מחברים או תמיכת פורמטים של השירות זמינים באותו אופן מקומית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('unstructured',3,'השוואה ובחירה','השוואה פדגוגית: השוו ל־Docling על אותו מסמך ואותה דרישת מקור. השוו ליכולות קליטה ב־RAGFlow, ובחנו שילוב התוצרים ב־Haystack או LlamaIndex. הבחירה צריכה להתחיל מדוגמאות מסמכים, ולא מרשימת מותגים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('unstructured',4,'פרטיות ואיכות','לפני שליחת מסמך ל־API חיצוני יש לבדוק הרשאה ומדיניות פרטיות. חוסר בכותרת או שינוי סדר טקסט עלולים לפגוע בשליפה; יש לשמור בדיקות חילוץ ולא להסתפק בתשובה שנראית משכנעת.');
