insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('unstructured','ספריית Python להכנת מסמכים, חילוץ רכיבי תוכן ומטא־נתונים וחלוקה למקטעים לפני שליפה.','הפרק ומדידת GitHub מתייחסים לספריית Python בקוד פתוח. C#/.NET יכול לצרוך שירות עיבוד דרך HTTP לפי API שנבחר; זו אינה תמיכת .NET מקורית בספרייה. SDKs ויכולות של שירות מסחרי צריכים להיבדק בנפרד.','verified','המאגר הרשמי של הפרויקט. Stars הם צילום מצב, ופעילות היא תאריך Commit בראש ברירת המחדל לפי UTC; אין ציון איכות או תפוצה.','2026-11-02T19:41:24.986Z');
