insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('microsoft-graphrag','היכרות עם REST/JSON, SQL, הרשאות ומודל שפה. מומלץ להתחיל בפרק RAG — יסודות וארכיטקטורה.','תרחיש לימודי מוצע: על מסמכים סינתטיים של פרויקטים, השוו שאלה נקודתית לשאלה על נושאים משותפים. מערכת .NET מציגה תשובה עם הפניות, ורק מסמכים מורשים נכללים באוסף המעובד.','הכינו זוג שאלות נקודתיות ורוחביות. תכננו מדידת איכות וזמן/עלות ל־baseline מול GraphRAG, ומקרה שבו מחיקת מסמך מחייבת עדכון תוצרים נגזרים.','הפרויקט שנבדק מציע מימוש באקוסיסטם Python. לא אומת SDK מקומי ל־C#/.NET; אפשר לתכנן שירות סביב התהליך ולצרוך תוצרים או HTTP. אין לזהות את הפרויקט עם Microsoft Agent Framework או להניח שוויון תמיכה ביניהם.','LightRAG היא גישה נוספת להשוואת גרף ושליפה. בסיס RAG באמצעות LlamaIndex או Haystack הוא קבוצת הביקורת, ולא פתרון נחות מעצם היעדר גרף.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-graphrag',0,'איזו בעיה הוא בוחן?','שליפה של מקטעים בודדים אינה תמיד מספיקה לשאלות על נושאים וקשרים לאורך אוסף שלם. GraphRAG בוחנת שילוב גרף ועיבוד מוקדם כדי לתמוך בסוגי שאלות נוספים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-graphrag',1,'איך בנוי התהליך?','אינדוקס מפיק ייצוגים וקשרים מהמסמכים, ושכבת Query משתמשת בתוצרים בדרכי חיפוש שונות. חילוץ בעזרת מודל עלול לטעות; גרף שנוצר אינו מאגר עובדות מאומת מעצם קיומו.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-graphrag',2,'שימושים מרכזיים','ניתוח קשרים ותמות על אוסף מסמכים ושאלות שמצריכות מבט רחב. מומלץ להשוות לשאילתות ממוקדות שבהן baseline פשוט עשוי להספיק, ולשמור יכולת לבדוק את המקורות שעליהם התשובה מבוססת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-graphrag',3,'השוואה ובחירה','השוואה פדגוגית: מול LightRAG בחנו אופן בניית גרף ושליפה; מול LlamaIndex ו־Haystack השוו תהליך בסיסי בעל אותו אוסף ושאלות. אין הצדקה להוסיף גרף רק משום שהוא מורכב יותר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-graphrag',4,'עלות, עדכניות ובטיחות','אינדוקס עשוי לדרוש קריאות מודל וזמן עיבוד. צריך לתכנן מה קורה כשמסמך משתנה או נמחק, וכיצד הרשאות המקור נשמרות בתוצרים נגזרים. אין כאן טענה שנמדדה עלות או איכות אצלנו.');
insert into academy.entry_sources (entry_id,position,source_url,title,checked_at,supports) values ('microsoft-graphrag',0,'https://microsoft.github.io/graphrag/','Microsoft GraphRAG — מקור רשמי','2026-11-02','תפקיד, תהליך ושפות; הדוגמאות וההשוואות הן תכנון פדגוגי של האקדמיה.');
