insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('microsoft-graphrag','מערכת RAG מבוססת גרף לבחינת קשרים ותשובות רוחביות על אוספי מידע ומקורות.','הפרויקט שנבדק מציע מימוש באקוסיסטם Python. לא אומת SDK מקומי ל־C#/.NET; אפשר לתכנן שירות סביב התהליך ולצרוך תוצרים או HTTP. אין לזהות את הפרויקט עם Microsoft Agent Framework או להניח שוויון תמיכה ביניהם.','verified','המאגר הרשמי של הפרויקט. Stars הם צילום מצב, ופעילות היא תאריך Commit בראש ברירת המחדל לפי UTC; אין ציון איכות או תפוצה.','2026-11-02T19:41:25.539Z');
