insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('lightrag','היכרות עם REST/JSON, SQL, הרשאות ומודל שפה. מומלץ להתחיל בפרק RAG — יסודות וארכיטקטורה.','דוגמה לימודית מוצעת: השוואת LightRAG ל־GraphRAG על אוסף נהלים סינתטי עם שאלות וקשרי נושאים ידועים. שירות .NET הוא שער גישה לתוצאות, והניסוי אינו מפעיל שרת ציבורי או צורך נתוני לקוחות.','כתבו תכנית להשוואת שתי גישות גרפיות ל־RAG פשוט. הגדירו איך מונעים משאלה של משתמש אחד לחשוף מידע השייך לארגון אחר.','ליבת הפרויקט שנבדקה היא Python, עם אפשרויות שירות/API. יישום C#/.NET או TypeScript יכול לצרוך שירות דרך HTTP לפי החוזה שנבחר; לא אומת כאן SDK ליבה מקומי ל־.NET.','Microsoft GraphRAG היא כלי ההשוואה המרכזי כאן; RAGFlow, Haystack ו־LlamaIndex מכסות חלופות ותפקידים נוספים. מספר Stars אינו ציון איכות לשליפה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('lightrag',0,'איזו בעיה הוא פותר?','LightRAG משלבת ידע גרפי ויכולות שליפה כדי לבנות הקשר לתשובות ממסמכים. היא מספקת נקודת מבט נוספת על מעבר מחיפוש מקטעים בלבד לתהליך המשתמש בקשרים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('lightrag',1,'איך בנויה המערכת?','מסמכים עוברים עיבוד ואינדוקס, ותוצרי ידע משמשים מסלולי שליפה. יש להבחין בין הספרייה, שכבת השרת ומנועי האחסון; בחירת backend משפיעה על מגבלות ותפעול.');
insert into academy.entry_sections (entry_id,position,title,body) values ('lightrag',2,'שימושים מרכזיים','השוואת חיפוש על קשרים ומקטעים באוסף ידע וניסוי ביישום שאלות ותשובות. התיעוד מציין שמאגרי ברירת מחדל מקומיים מיועדים גם לניסוי; בחירת תשתית ייצור מחייבת בדיקה נפרדת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('lightrag',3,'השוואה ובחירה','השוואה פדגוגית: מול Microsoft GraphRAG הגדירו אוסף ושאלות משותפים, ובחנו מקורות, זמן ועלות. מול RAGFlow השוו מערכת ושכבת שירות; מול Haystack השוו את כמות השליטה וההרכבה בקוד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('lightrag',4,'אחסון ובטיחות','שמרו מזהי מקורות ותכננו מחיקה ועדכון של תוצרים. הפרידו סביבת ניסוי מנתוני ארגון, ובדקו הרשאות, גיבוי ומגבלות משאבים לפני הפעלת שרת. אין להציג תוצאה מחקרית כהבטחת איכות למקרה שלכם.');
insert into academy.entry_sources (entry_id,position,source_url,title,checked_at,supports) values ('lightrag',0,'https://github.com/HKUDS/LightRAG','LightRAG — מקור רשמי','2026-11-02','תפקיד, תהליך ושפות; הדוגמאות וההשוואות הן תכנון פדגוגי של האקדמיה.');
