insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('lightrag','מערכת RAG המשלבת גרף ידע ושליפה, להשוואת גישות מתקדמות לחיפוש ולבניית הקשר.','ליבת הפרויקט שנבדקה היא Python, עם אפשרויות שירות/API. יישום C#/.NET או TypeScript יכול לצרוך שירות דרך HTTP לפי החוזה שנבחר; לא אומת כאן SDK ליבה מקומי ל־.NET.','verified','המאגר הרשמי של הפרויקט. Stars הם צילום מצב, ופעילות היא תאריך Commit בראש ברירת המחדל לפי UTC; אין ציון איכות או תפוצה.','2026-11-02T19:41:26.105Z');
