insert into academy.category_guides (category_id,title,introduction,note) values ('04','איך ללמוד מערכות RAG וידע?','מתקדמים מהארכיטקטורה להכנת מסמכים, להרכבת מערכת ורק אחר כך לשליפה מבוססת גרף. הסוגים בטבלה שונים: פרק מושגים, מסגרות, מערכת משולבת וכלי הכנת מסמכים.','מסדי נתונים וקטוריים נלמדים בקטגוריה 05; הערכה וניטור ב־10. גרף אינו דרישה לכל יישום RAG, וקריאת HTTP מ־.NET אינה SDK מקומי.');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('04',0,'rag-fundamentals','תחילה מבינים מה מאנדקסים, איך שולפים הקשר ואיך בודקים מקורות.','ליסודות RAG');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('04',1,'docling','בודקים איכות חילוץ ומבנה של מסמכים, ומשווים ל־Unstructured.','להכנת מסמכים');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('04',2,'llamaindex','בונים baseline, ואז משווים ל־Haystack ולמערכת RAGFlow.','לפרק LlamaIndex הקיים');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('04',3,'microsoft-graphrag','רק אחרי baseline בוחנים מה מוסיף גרף ומשווים ל־LightRAG.','להעמקה בשליפה מבוססת גרף');
