-- RAG content expansion only: no schema or existing-entry changes.
begin;
select pg_advisory_xact_lock(hashtext('academy-migrations'));
do $$ begin
 if (select max(version) from academy.schema_migrations) is distinct from 6 then raise exception 'Expected schema version 6'; end if;
 if exists(select 1 from academy.entries where slug in ('rag-fundamentals','haystack','ragflow','docling','unstructured','microsoft-graphrag','lightrag') or lower(name) in ('rag — יסודות וארכיטקטורה','haystack','ragflow','docling','unstructured','microsoft graphrag','lightrag')) then raise exception 'RAG entry already exists'; end if;
 if exists(select 1 from academy.repositories where url in ('https://github.com/deepset-ai/haystack','https://github.com/infiniflow/ragflow','https://github.com/docling-project/docling','https://github.com/Unstructured-IO/unstructured','https://github.com/microsoft/graphrag','https://github.com/HKUDS/LightRAG')) then raise exception 'RAG repository already represented'; end if;
 if exists(select 1 from academy.category_guides where category_id='04') then raise exception 'Review existing category guide'; end if;
 if (select count(*) from academy.entries where slug='llamaindex')<>1 then raise exception 'Existing LlamaIndex missing'; end if;
end $$;
do $$ begin
 if (select count(*) from academy.entries where slug in ('rag-fundamentals','haystack','ragflow','docling','unstructured','microsoft-graphrag','lightrag'))<>7 then raise exception 'RAG import incomplete'; end if;
 if (select count(*) from academy.entry_relations where entry_id in ('rag-fundamentals','haystack','ragflow','docling','unstructured','microsoft-graphrag','lightrag'))<>25 then raise exception 'RAG relation missing'; end if;
end $$;
commit;
